20	import org.springframework.stereotype.Service;
21	import org.springframework.transaction.annotation.Transactional;
22	import org.springframework.web.server.ResponseStatusException;
23	
24	/** The claims people make on a sheet. */
25	@Service
26	public class ClaimService {
27	
28	    /** The number sequence of claims in no period. */
29	    private static final String NO_PERIOD = "X";
30	
31	    private final ClaimRepository claims;
32	    private final PersonRepository people;
33	    private final RateRepository rates;
34	    private final PeriodRepository periods;
35	    private final SheetService sheets;
36	    private final RollupService rollup;
37	    private final SettingsService settings;
38	    private final Audit audit;
39	
40	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
41	            PeriodRepository periods, SheetService sheets, RollupService rollup, SettingsService settings,
42	            Audit audit) {
43	        this.claims = claims;
44	        this.people = people;
45	        this.rates = rates;
46	        this.periods = periods;
47	        this.sheets = sheets;
48	        this.rollup = rollup;
49	        this.settings = settings;
50	        this.audit = audit;
51	    }
52	
53	    /** All the claims on the sheet, newest first. */
54	    @Transactional(readOnly = true)
55	    public List<Claim> list(String sheetId) {
56	        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
57	    }
58	
59	    /**
60	     * Adds a claim for the person; a missing date takes the sheet's today. Refused when dated in a closed period or
61	     * after the person's retirement date, and a correction (a negative amount) unless it corrects a settled claim of
62	     * the person.
63	     */
64	    @Transactional
65	    public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
66	            String corrects) {
67	        LocalDate on = dateOrToday(sheetId, date);
68	        refuseInClosedPeriod(sheetId, on);
69	        RollupService.Snapshot before = rollup.snapshot(sheetId);
70	        Person person = person(sheetId, personId);
71	        refuseAfterRetirement(person, on);
72	        String corrected = correctedNumber(sheetId, personId, amount, corrects);
73	        Claim claim = new Claim(sheetId, personId, scaled(amount), on, noteOf(note));
74	        claim.setCorrects(corrected);
75	        claim.setRoundsOn(roundsOn(sheetId, corrected, on));
76	        claim.setDueBy(on.plusDays(sheets.load(sheetId).termsFor(person.gradeOn(on), on)));
77	        logStatus(by, sheetId, person, claim);
78	        Claim added = claims.saveAndFlush(claim);
79	        audit.recordOnCommit(record("CLAIM_ADDED", by, person, added));
80	        rollup.recordChanges(by, sheetId, before);
81	        return added;
82	    }
83	
84	    /**
85	     * Edits a claim; refused unless it is a draft, when it is dated in a closed period, or when the edit would date
86	     * it in one. An open claim is changed by voiding it and adding a new one.
87	     */
88	    @Transactional
89	    public Claim update(String by, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
90	            String corrects) {
91	        LocalDate on = dateOrToday(sheetId, date);
92	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
93	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
94	        if (claim.getStatus() != ClaimStatus.DRAFT) {
95	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
96	        }
97	        refuseInClosedPeriod(sheetId, claim.getDate());
98	        refuseInClosedPeriod(sheetId, on);
99	        refuseAfterRetirement(person(sheetId, claim.getPersonId()), on);
100	        String corrected = correctedNumber(sheetId, claim.getPersonId(), amount, corrects);
101	        RollupService.Snapshot before = rollup.snapshot(sheetId);
102	        claim.setAmount(scaled(amount));
103	        claim.setCorrects(corrected);
104	        claim.setDate(on);
105	        claim.setRoundsOn(roundsOn(sheetId, corrected, on));
106	        claim.setNote(noteOf(note));
107	        Claim saved = claims.saveAndFlush(claim);
108	        audit.recordOnCommit(record("CLAIM_EDITED", by, person(sheetId, saved.getPersonId()), saved));
109	        rollup.recordChanges(by, sheetId, before);
110	        return saved;
111	    }
