113	    /**
114	     * Moves the claim to the status; a change its status does not allow is refused, as is settling by the user
115	     * who opened it, and any change to a claim dated in a closed period. A clerk settling a claim whose due is above
116	     * the clerk limit makes it PENDING instead, for a steward to approve or reject.
117	     */
118	    @Transactional
119	    public Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next) {
120	        Claim claim = lockedClaim(sheetId, id);
121	        switch (next) {
122	            case OPEN -> settings.refuseUnlessMay(sheetId, by, "open");
123	            case SETTLED -> settings.refuseUnlessMay(sheetId, by, "settle");
124	            case VOID -> settings.refuseUnlessMay(sheetId, by, "void");
125	            default -> {
126	            }
127	        }
128	        RollupService.Snapshot before = rollup.snapshot(sheetId);
129	        // settling is the step from OPEN; a pending claim is settled by approving it
130	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
131	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
132	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
133	            throw new ResponseStatusException(HttpStatus.CONFLICT,
134	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
135	        }
136	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
137	            throw new ResponseStatusException(HttpStatus.CONFLICT,
138	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
139	        }
140	        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
141	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
142	        }
143	        if (next == ClaimStatus.OPEN) {
144	            number(sheetId, claim);
145	            claim.setOpenedBy(by);
146	        }
147	        Person person = person(sheetId, claim.getPersonId());
148	        String event = switch (next) {
149	            case OPEN -> "CLAIM_OPENED";
150	            case SETTLED -> "CLAIM_SETTLED";
151	            case VOID -> "CLAIM_VOIDED";
152	            case DRAFT, PENDING -> throw new IllegalStateException();
153	        };
154	        String tail = "";
155	        if (next == ClaimStatus.SETTLED) {
156	            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
157	            // force on the claim's date, with the late charge it has gained by today; with none it stays live
158	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
159	                    : liveDue(sheetId, person, claim);
160	            BigDecimal fixed = claim.isCorrection() ? figure
161	                    : withLateCharge(figure, claim, sheets.load(sheetId));
162	            refuseWithoutProof(sheetId, claim, fixed);
163	            if (settings.aboveClerkLimit(sheetId, by, fixed)) {
164	                next = ClaimStatus.PENDING;
165	                event = "CLAIM_PENDING";
166	            } else {
167	                claim.setSettledDue(fixed);
168	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
169	            }
170	        }
171	        claim.setStatus(next);
172	        logStatus(by, sheetId, person, claim);
173	        Claim saved = claims.saveAndFlush(claim);
174	        audit.recordOnCommit(record(event, by, person, saved) + tail);
175	        rollup.recordChanges(by, sheetId, before);
176	        return saved;
177	    }
