179	    /**
180	     * Defers an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts
181	     * in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that is
182	     * not OPEN, a date not after today, and in a closed period.
183	     */
184	    @Transactional
185	    public Claim defer(String by, String sheetId, Long id, LocalDate until) {
186	        Claim claim = lockedClaim(sheetId, id);
187	        if (claim.getStatus() != ClaimStatus.OPEN) {
188	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
189	        }
190	        LocalDate today = sheets.load(sheetId).getToday();
191	        if (until == null || (today != null && !until.isAfter(today))) {
192	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
193	                    "A claim can only be deferred to a date after the sheet's today.");
194	        }
195	        RollupService.Snapshot before = rollup.snapshot(sheetId);
196	        claim.setDeferredUntil(until);
197	        Claim saved = claims.saveAndFlush(claim);
198	        audit.recordOnCommit(record("CLAIM_DEFERRED", by, person(sheetId, saved.getPersonId()), saved) + " until="
199	                + until);
200	        rollup.recordChanges(by, sheetId, before);
201	        return saved;
202	    }
