204	    /**
205	     * Raises the claim's proofs count by one. Refused for a SETTLED or VOID claim, and in a closed period.
206	     */
207	    @Transactional
208	    public Claim addProof(String by, String sheetId, Long id) {
209	        Claim claim = lockedClaim(sheetId, id);
210	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
211	            throw new ResponseStatusException(HttpStatus.CONFLICT,
212	                    "A " + claim.getStatus() + " claim cannot take a proof.");
213	        }
214	        claim.addProof();
215	        Claim saved = claims.saveAndFlush(claim);
216	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", by, person(sheetId, saved.getPersonId()), saved)
217	                + " proofs=" + saved.getProofs());
218	        return saved;
