221	    /**
222	     * Refuses settling or approving the claim at the due (null for n/a) when the due is above the proof threshold in
223	     * force on the claim's date and the claim has no proof; an n/a due is within any threshold.
224	     */
225	    private void refuseWithoutProof(String sheetId, Claim claim, BigDecimal due) {
226	        BigDecimal threshold = sheets.load(sheetId).proofThresholdOn(claim.getDate());
227	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
228	            throw new ResponseStatusException(HttpStatus.CONFLICT,
229	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof first.");
230	        }
231	    }
