233	    /**
234	     * A steward approves a pending claim: it is settled, its due fixed at the live figure it shows now. Refused
235	     * unless it is pending, unless the user is a steward, for the user who opened it, and in a closed period.
236	     */
237	    @Transactional
238	    public Claim approve(String by, String sheetId, Long id) {
239	        Claim claim = pendingClaim(by, sheetId, id);
240	        if (by.equals(claim.getOpenedBy())) {
241	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot approve it.");
242	        }
243	        RollupService.Snapshot before = rollup.snapshot(sheetId);
244	        Person person = person(sheetId, claim.getPersonId());
245	        BigDecimal fixed = due(sheetId, person, claim);
246	        refuseWithoutProof(sheetId, claim, fixed);
247	        claim.setSettledDue(fixed);
248	        claim.setStatus(ClaimStatus.SETTLED);
249	        logStatus(by, sheetId, person, claim);
250	        Claim saved = claims.saveAndFlush(claim);
251	        audit.recordOnCommit(record("CLAIM_APPROVED", by, person, saved) + " due="
252	                + (fixed == null ? "n/a" : fixed.toPlainString()));
253	        rollup.recordChanges(by, sheetId, before);
254	        return saved;
255	    }
