257	    /**
258	     * A steward re-settles a settled claim: its due is frozen again at the figure it would have today as an open
259	     * claim bound by no statement (today's rates, grades and floor, with the late charge it has gained by today; a
260	     * correction gains none). Refused unless the user is a steward, unless it is settled, and in a closed period.
261	     */
262	    @Transactional
263	    public Claim resettle(String by, String sheetId, Long id) {
264	        if (!settings.isSteward(sheetId, by)) {
265	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
266	        }
267	        Claim claim = lockedClaim(sheetId, id);
268	        if (claim.getStatus() != ClaimStatus.SETTLED) {
269	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
270	        }
271	        RollupService.Snapshot before = rollup.snapshot(sheetId);
272	        Person person = person(sheetId, claim.getPersonId());
273	        BigDecimal old = claim.getSettledDue();
274	        BigDecimal live = liveDue(sheetId, person, claim);
275	        BigDecimal fixed = claim.isCorrection() ? live : withLateCharge(live, claim, sheets.load(sheetId));
276	        claim.setSettledDue(fixed);
277	        logStatus(by, sheetId, person, claim);
278	        Claim saved = claims.saveAndFlush(claim);
279	        audit.recordOnCommit(record("CLAIM_RESETTLED", by, person, saved) + " old=" + text(old) + " new="
280	                + text(fixed));
281	        rollup.recordChanges(by, sheetId, before);
282	        return saved;
283	    }
