285	    /**
286	     * A steward rejects a pending claim with a reason: it is open again, bound again by its person's last statement
287	     * when that included it. Refused unless it is pending, unless the user is a steward, without a reason, and in a
288	     * closed period.
289	     */
290	    @Transactional
291	    public Claim reject(String by, String sheetId, Long id, String reason) {
292	        String why = reason == null ? "" : reason.strip();
293	        if (why.isEmpty()) {
294	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A rejection needs a reason.");
295	        }
296	        Claim claim = pendingClaim(by, sheetId, id);
297	        RollupService.Snapshot before = rollup.snapshot(sheetId);
298	        claim.setStatus(ClaimStatus.OPEN);
299	        logStatus(by, sheetId, person(sheetId, claim.getPersonId()), claim);
300	        Claim saved = claims.saveAndFlush(claim);
301	        audit.recordOnCommit(record("CLAIM_REJECTED", by, person(sheetId, saved.getPersonId()), saved)
302	                + " reason=" + why);
303	        rollup.recordChanges(by, sheetId, before);
304	        return saved;
305	    }
