307	    /**
308	     * A user whose role may reassign (a steward by the standing rule) moves a DRAFT, OPEN or PENDING claim to another person of the sheet. It keeps its number and date,
309	     * loses any figure a statement bound it to (it is live again until its new person's next statement), and is
310	     * listed as its new person's newest claim. Refused unless the user's role may reassign, for a settled or voided claim,
311	     * to the person it is already with, in a closed period, and when it is dated after the new person's retirement.
312	     */
313	    @Transactional
314	    public Claim reassign(String by, String sheetId, Long id, Long toPersonId) {
315	        settings.refuseUnlessMay(sheetId, by, "reassign");
316	        Claim claim = lockedClaim(sheetId, id);
317	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
318	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot move.");
319	        }
320	        if (claim.getPersonId().equals(toPersonId)) {
321	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's.");
322	        }
323	        Person from = person(sheetId, claim.getPersonId());
324	        Person to = person(sheetId, toPersonId);
325	        refuseAfterRetirement(to, claim.getDate());
326	        RollupService.Snapshot before = rollup.snapshot(sheetId);
327	        claim.setPersonId(to.getId());
328	        claim.unbind();
329	        Claim saved = claims.saveAndFlush(claim);
330	        claims.relist(saved.getId());
331	        audit.recordOnCommit(record("CLAIM_REASSIGNED", by, to, saved) + " from=" + from.getName() + " to="
332	                + to.getName());
333	        rollup.recordChanges(by, sheetId, before);
334	        return saved;
335	    }
