342	    /** The pending claim, locked, for a steward to decide; refused otherwise. */
343	    private Claim pendingClaim(String by, String sheetId, Long id) {
344	        Claim claim = lockedClaim(sheetId, id);
345	        if (claim.getStatus() != ClaimStatus.PENDING) {
346	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
347	        }
348	        if (!settings.isSteward(sheetId, by)) {
349	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim.");
350	        }
