354	    /** The claim, locked; refused when it is dated in a closed period. */
355	    private Claim lockedClaim(String sheetId, Long id) {
356	        // the sheet is locked before the claim, in the order a period closing takes them
357	        sheets.lock(sheetId);
358	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
359	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
360	        refuseInClosedPeriod(sheetId, claim.getDate());
361	        return claim;
362	    }
