364	    /**
365	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
366	     * after it, the next in the sequence of the period the claim is dated in (X for none), else the sheet's next.
367	     * The sheet is locked, so two claims opened at once never get the same one.
368	     */
369	    private void number(String sheetId, Claim claim) {
370	        Sheet sheet = sheets.load(sheetId);
371	        LocalDate from = sheet.getPeriodNumberingFrom();
372	        if (from == null || sheet.getToday().isBefore(from)) {
373	            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
374	            return;
375	        }
376	        String sequence = periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
377	                claim.getDate(), claim.getDate()).map(Period::getName).orElse(NO_PERIOD);
378	        Long last = claims.lastInSequence(sheetId, sequence);
379	        claim.numberIn(sequence, last == null ? 1 : last + 1);
380	    }
