382	    /**
383	     * The claim's live due: at the rate its person's grade in force on its date has in force on that date, and at least the sheet's
384	     * floor in force on its date (a correction has none), rounded as the sheet's policy date decides for it; null (n/a) with none.
385	     */
386	    public BigDecimal liveDue(String sheetId, Person person, Claim claim) {
387	        Sheet sheet = sheets.load(sheetId);
388	        BigDecimal floor = claim.isCorrection() ? null : sheet.floorOn(claim.getDate());
389	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
390	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
391	                .map(pct -> floored(dueOn(claim.getAmount(), pct, rounding), floor)).orElse(null);
392	    }
