394	    /**
395	     * The figure the claim shows and totals: its settled due, else the one a statement bound it to (not while it is
396	     * pending), else live.
397	     */
398	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
399	        if (claim.getSettledDue() != null) {
400	            return claim.getSettledDue();
401	        }
402	        return claim.isBound() ? claim.getStatedDue() : liveDue(sheetId, person, claim);
403	    }
404	
405	    /**
406	     * The due the claim shows and totals: its figure, with the late charge an open (or pending) overdue claim has gained; a
407	     * correction gains none.
408	     */
409	    public BigDecimal due(String sheetId, Person person, Claim claim) {
410	        BigDecimal figure = figure(sheetId, person, claim);
411	        return claim.getStatus().isOpen() && !claim.isCorrection()
412	                ? withLateCharge(figure, claim, sheets.load(sheetId))
413	                : figure;
414	    }
415	
416	    /**
417	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
418	     * due-by) by the sheet's today: for each such boundary (its due-by plus 30, 60, 90 ... days), the sheet's late
419	     * percent in force on that boundary date of the figure, rounded like its due; a boundary whose percent is 0.00
420	     * adds nothing. A deferred claim is not overdue. The charge is never bound by a statement: it keeps following the
421	     * sheet's today and its policy date.
422	     */
423	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Sheet sheet) {
424	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
425	            return figure;
426	        }
427	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday());
428	        long periods = overdue > 0 ? overdue / 30 : 0;
429	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
430	        BigDecimal due = figure;
431	        for (long k = 1; k <= periods; k++) {
432	            BigDecimal latePct = sheet.latePctOn(claim.getDueBy().plusDays(30 * k));
433	            if (latePct.signum() != 0) {
434	                due = due.add(dueOn(figure, latePct, rounding));
435	            }
436	        }
437	        return due;
438	    }
