440	    /**
441	     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
442	     * the transaction ends, so a period closing at the same moment is checked in turn.
443	     */
444	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
445	        sheets.lock(sheetId);
446	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
447	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
448	        }
449	    }
