452	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
453	     * claim of the person, else refused; null for any other claim.
454	     */
455	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
456	        if (amount.signum() >= 0) {
457	            return null;
458	        }
459	        corrects = corrects == null ? null : corrects.strip();
460	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
461	                ClaimStatus.SETTLED)) {
462	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
463	                    "A negative amount must correct a settled claim of the person, named by its number.");
464	        }
465	        return corrects;
466	    }
