468	    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
469	    private static void refuseAfterRetirement(Person person, LocalDate date) {
470	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
471	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
472	                    "That claim is dated after the person's retirement.");
473	        }
474	    }
