481	    /** The audit line about a claim; one that has a number ends with it. */
482	    private static String record(String event, String by, Person person, Claim c) {
483	        String number = c.getNumber();
484	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
485	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
486	                + (number != null ? " number=" + number : "");
