489	    /**
490	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
491	     * negative amount rounds like its positive).
492	     */
493	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
494	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
495	    }
496	
497	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
498	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
499	        return corrects == null ? on
500	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
501	    }
502	
503	    /** The due raised to the floor when it is below it. */
504	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
505	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
506	    }
507	
508	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
509	        return date != null ? date : sheets.load(sheetId).getToday();
510	    }
511	
512	    private static String text(BigDecimal value) {
513	        return value == null ? "n/a" : value.toPlainString();
514	    }
515	
516	    private static BigDecimal scaled(BigDecimal amount) {
517	        return amount.setScale(2, RoundingMode.UNNECESSARY);
518	    }
519	
520	    private static String noteOf(String note) {
521	        return note == null ? "" : note.strip();
522	    }
